-- CalfManager Pro 2.3.0. Einmalig im Supabase SQL Editor ausführen.
create extension if not exists pgcrypto;
create table if not exists public.farm_growth_settings(farm_id uuid primary key references public.farms(id) on delete cascade,min_gain_g integer not null default 700 check(min_gain_g between 0 and 3000));
alter table public.farm_growth_settings enable row level security;
drop policy if exists "growth read" on public.farm_growth_settings;
create policy "growth read" on public.farm_growth_settings for select to authenticated using(public.is_farm_member(farm_id));
drop policy if exists "growth insert" on public.farm_growth_settings;
create policy "growth insert" on public.farm_growth_settings for insert to authenticated with check(public.is_farm_owner(farm_id));
drop policy if exists "growth update" on public.farm_growth_settings;
create policy "growth update" on public.farm_growth_settings for update to authenticated using(public.is_farm_owner(farm_id)) with check(public.is_farm_owner(farm_id));
create table if not exists public.farm_invitations(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,email text not null,token_hash text not null unique,status text not null default 'pending' check(status in ('pending','accepted','revoked')),expires_at timestamptz not null default now()+interval '7 days',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),accepted_at timestamptz);
create index if not exists idx_invites_farm on public.farm_invitations(farm_id);
alter table public.farm_invitations enable row level security;
-- Kein direkter Tabellenzugriff: ausschließlich SECURITY DEFINER RPC mit Rollenprüfung.
revoke all on public.farm_invitations from anon,authenticated;
create or replace function public.list_farm_invitations(p_farm_id uuid) returns table(id uuid,email text,status text,expires_at timestamptz) language plpgsql stable security definer set search_path='' as $$begin if not public.is_farm_owner(p_farm_id) then raise exception 'Kein Zugriff';end if;return query select i.id,i.email,i.status,i.expires_at from public.farm_invitations i where i.farm_id=p_farm_id order by i.created_at desc limit 100;end$$;
create or replace function public.create_farm_invitation(p_farm_id uuid,p_email text) returns text language plpgsql security definer set search_path='' as $$declare v_token text;v_email text:=lower(trim(p_email));begin if not public.is_farm_owner(p_farm_id) then raise exception 'Nur Betriebsleiter dürfen einladen';end if;if length(v_email)>254 or v_email !~ '^[^@ ]+@[^@ ]+\.[^@ ]+$' then raise exception 'Ungültige E-Mail-Adresse';end if;if (select count(*) from public.farm_invitations where farm_id=p_farm_id and created_at>now()-interval '1 hour')>=15 then raise exception 'Zu viele Einladungen. Bitte später erneut versuchen';end if;update public.farm_invitations set status='revoked' where farm_id=p_farm_id and email=v_email and status='pending';v_token:=encode(gen_random_bytes(32),'hex');insert into public.farm_invitations(farm_id,email,token_hash,created_by) values(p_farm_id,v_email,encode(digest(v_token,'sha256'),'hex'),auth.uid());return v_token;end$$;
create or replace function public.revoke_farm_invitation(p_invitation_id uuid) returns void language plpgsql security definer set search_path='' as $$begin update public.farm_invitations set status='revoked' where id=p_invitation_id and status='pending' and public.is_farm_owner(farm_id);if not found then raise exception 'Einladung nicht gefunden oder keine Berechtigung';end if;end$$;
create or replace function public.accept_farm_invitation(p_token text) returns uuid language plpgsql security definer set search_path='' as $$declare v_inv public.farm_invitations%rowtype;v_email text;begin if auth.uid() is null then raise exception 'Bitte zuerst anmelden';end if;select lower(email) into v_email from auth.users where id=auth.uid() and email_confirmed_at is not null;if v_email is null then raise exception 'Bitte E-Mail-Adresse bestätigen';end if;select * into v_inv from public.farm_invitations where token_hash=encode(digest(p_token,'sha256'),'hex') for update;if not found or v_inv.status<>'pending' or v_inv.expires_at<=now() then raise exception 'Einladung ungültig oder abgelaufen';end if;if v_inv.email<>v_email then raise exception 'Bitte mit der eingeladenen E-Mail-Adresse anmelden';end if;insert into public.farm_members(farm_id,user_id,role) values(v_inv.farm_id,auth.uid(),'employee') on conflict(farm_id,user_id) do nothing;update public.farm_invitations set status='accepted',accepted_at=now() where id=v_inv.id;return v_inv.farm_id;end$$;
create table if not exists public.farm_owner_transfers(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id) on delete cascade,old_owner uuid not null references auth.users(id),new_owner uuid not null references auth.users(id),changed_at timestamptz not null default now());
alter table public.farm_owner_transfers enable row level security;
revoke all on public.farm_owner_transfers from anon,authenticated;
create or replace function public.transfer_farm_ownership(p_farm_id uuid,p_new_owner uuid) returns void language plpgsql security definer set search_path='' as $$declare v_old uuid:=auth.uid();begin if not public.is_farm_owner(p_farm_id) then raise exception 'Nur der Betriebsleiter darf übergeben';end if;if p_new_owner=v_old then raise exception 'Bitte anderen Mitarbeiter wählen';end if;perform 1 from public.farm_members where farm_id=p_farm_id for update;if not exists(select 1 from public.farm_members where farm_id=p_farm_id and user_id=p_new_owner and role='employee') then raise exception 'Neuer Betriebsleiter muss Mitarbeiter sein';end if;update public.farm_members set role='employee' where farm_id=p_farm_id and user_id=v_old and role='owner';update public.farm_members set role='owner' where farm_id=p_farm_id and user_id=p_new_owner;insert into public.farm_owner_transfers(farm_id,old_owner,new_owner) values(p_farm_id,v_old,p_new_owner);end$$;
-- Ersetze vorhandene RPC, um die letzte Anmeldung nur Betriebsleitern offenzulegen.
drop function if exists public.list_farm_members(uuid);
create function public.list_farm_members(p_farm_id uuid) returns table(user_id uuid,role text,email text,last_sign_in_at timestamptz) language plpgsql stable security definer set search_path='' as $$begin if not public.is_farm_member(p_farm_id) then raise exception 'Kein Zugriff';end if;return query select fm.user_id,fm.role,u.email::text,case when public.is_farm_owner(p_farm_id) then u.last_sign_in_at else null::timestamptz end from public.farm_members fm join auth.users u on u.id=fm.user_id where fm.farm_id=p_farm_id order by fm.created_at;end$$;
revoke all on function public.list_farm_invitations(uuid),public.create_farm_invitation(uuid,text),public.revoke_farm_invitation(uuid),public.accept_farm_invitation(text),public.transfer_farm_ownership(uuid,uuid),public.list_farm_members(uuid) from public;
grant execute on function public.list_farm_invitations(uuid),public.create_farm_invitation(uuid,text),public.revoke_farm_invitation(uuid),public.accept_farm_invitation(text),public.transfer_farm_ownership(uuid,uuid),public.list_farm_members(uuid) to authenticated;
-- Alte direkte Aufnahme sperren, damit Einladungen nicht umgangen werden.
revoke execute on function public.add_existing_member(uuid,text) from authenticated;
